def render(code,t):
    switch=''.join(f'<a href="/{x}/waltham-ventures.html"'+(' aria-current="page"' if x==code else '')+f'>{"DK" if x=="dk" else x.upper()}</a>' for x in ['dk','no','en','de'])
    steps=''.join(f'<article><b>{i:02}</b><h3>{h}</h3><p>{p}</p></article>' for i,(h,p) in enumerate(t['steps'],1))
    ventures=''.join(f'<article><span>{s}</span><h3>{h}</h3><p>{p}</p></article>' for s,h,p in t['ventures'])
    return f'''<!doctype html><html lang="{t['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Waltham Ventures — from market signal to launched venture."><title>Waltham Ventures</title><link rel="stylesheet" href="../css/styles.css"><link rel="stylesheet" href="../css/ventures.css"></head><body><header class="venture-nav"><div class="wrap"><a class="logo" href="index.html">Waltham<span>.</span><small>Ventures</small></a><nav class="language-switcher">{switch}</nav><a class="back" href="index.html">← {t['back']}</a></div></header><main><section class="venture-hero"><div class="wrap"><p class="eyebrow">{t['eyebrow']}</p><h1>{t['hero']}</h1><p class="hero-lead">{t['lead']}</p><a class="button primary" href="#contact">{t['cta']}</a></div></section><section class="section wrap"><div class="speed-grid"><div><p class="label">{t['speed_label']}</p><p class="speed-statement">{t['speed_h']}</p></div><div class="copy"><p>{t['speed_p']}</p><p class="reality-note">{t['reality']}</p></div></div></section><section class="section venture-paths"><div class="wrap"><p class="label">{t['paths_label']}</p><h2>{t['paths_h']}</h2><div class="two-paths"><article class="path-card"><h3>{t['own_h']}</h3><p>{t['own_p']}</p></article><article class="path-card"><h3>{t['your_h']}</h3><p>{t['your_p']}</p></article></div></div></section><section class="section venture-process"><div class="wrap"><p class="label">{t['process_label']}</p><h2>{t['process_h']}</h2><div class="venture-steps">{steps}</div></div></section><section class="section wrap"><p class="label">{t['portfolio_label']}</p><h2>{t['portfolio_h']}</h2><div class="venture-portfolio">{ventures}</div></section><section class="section venture-urgency"><div class="wrap"><p class="label">{t['urgent_label']}</p><h2>{t['urgent_h']}</h2><div class="copy"><p>{t['urgent_p']}</p></div></div></section><section class="section wrap" id="contact"><div class="venture-contact"><div><p class="label">Waltham Ventures</p><h2>{t['contact_h']}</h2><p class="copy">{t['contact_p']}</p></div><div class="contact-card"><a class="button primary" href="mailto:waltham@me.com?subject=Waltham%20Ventures">{t['send']}</a></div></div></section></main><footer><div class="wrap"><a class="logo" href="index.html">Waltham<span>.</span></a><p>Consulting · Insight · Ventures.</p></div></footer><script src="/js/cookie-notice.js"></script></body></html>'''

for code,t in DATA.items():
    (ROOT/code/t['file']).write_text(render(code,t),encoding='utf-8')
